select city, case when rating >= 3.8 then 'HIGH' else 'LOW' end as rating_tier, percentile_approx(rating, 0.95) as rating_p95, round(sum(rating) / nullif(count(case when country = 'DE' then 1 end), 0), 2) as rating_per_de, count(*) filter (where city = 'London') as london_rows, rank() over (partition by city order by round(sum(rating) / nullif(count(case when country = 'DE' then 1 end), 0), 2) desc) as rating_per_de_rank from suppliers group by 1, 2
